   const isDark = theme === 'dark'
   return (
      <button
        type="button"
        className="theme-toggle"
        onClick={onToggle}
        aria-label={isDark ? 'Zu hellem Modus wechseln' : 'Zu dunklem Modus wechseln'}
        title={isDark ? 'Helles Design' : 'Dunkles Design'}
